"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[5710],{69614(e,t,n){n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>o,default:()=>d,frontMatter:()=>s,metadata:()=>h,toc:()=>l});var i=n(74848),a=n(28453);const s={title:"Detective Conan vs Steins;Gate",date:new Date("2026-10-07T00:00:00.000Z"),lang:"en",section:"freewrite",topic:"fiction-critique",category:"\u8a8d\u77e5\u8207\u6558\u4e8b",article_tags:{zh:["\u52d5\u6f2b\u8a55\u8ad6","\u89d2\u8272\u5851\u9020","\u6558\u4e8b\u7d50\u69cb","\u611b\u60c5\u8207\u6289\u64c7","\u7406\u8ad6\u6846\u67b6\u6279\u5224"],en:["anime-review","character-writing","narrative-structure","love-and-choice","framework-critique"]},keywords:["Detective Conan","Steins;Gate","Ai Haibara","Kurisu Makise","Rintaro Okabe","World Lines"],summary:"Same parts, inverted structure: one story freezes time to avoid a choice; the other makes the choice carry real weight. On love and the inner life, Steins;Gate is far more nuanced, complete, and three-dimensional.",status:"published",reading_time:12,sidebar_label:"Detective Conan vs Steins;Gate",sidebar_position:20261007,description:"Same parts, inverted structure: one story freezes time to avoid a choice; the other makes the choice carry real weight. On love and the inner life, Steins;Gate is far more nuanced, complete, and three-dimensional."},o="Detective Conan vs Steins;Gate",h={id:"Diary/\u540d\u5075\u63a2\u67ef\u5357 vs \u547d\u904b\u77f3\u4e4b\u9580",title:"Detective Conan vs Steins;Gate",description:"Same parts, inverted structure: one story freezes time to avoid a choice; the other makes the choice carry real weight. On love and the inner life, Steins;Gate is far more nuanced, complete, and three-dimensional.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/Diary/\u540d\u5075\u63a2\u67ef\u5357 vs \u547d\u904b\u77f3\u4e4b\u9580.md",sourceDirName:"Diary",slug:"/Diary/\u540d\u5075\u63a2\u67ef\u5357 vs \u547d\u904b\u77f3\u4e4b\u9580",permalink:"/en/docs/Diary/\u540d\u5075\u63a2\u67ef\u5357 vs \u547d\u904b\u77f3\u4e4b\u9580",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:20261007,frontMatter:{title:"Detective Conan vs Steins;Gate",date:"2026-10-07T00:00:00.000Z",lang:"en",section:"freewrite",topic:"fiction-critique",category:"\u8a8d\u77e5\u8207\u6558\u4e8b",article_tags:{zh:["\u52d5\u6f2b\u8a55\u8ad6","\u89d2\u8272\u5851\u9020","\u6558\u4e8b\u7d50\u69cb","\u611b\u60c5\u8207\u6289\u64c7","\u7406\u8ad6\u6846\u67b6\u6279\u5224"],en:["anime-review","character-writing","narrative-structure","love-and-choice","framework-critique"]},keywords:["Detective Conan","Steins;Gate","Ai Haibara","Kurisu Makise","Rintaro Okabe","World Lines"],summary:"Same parts, inverted structure: one story freezes time to avoid a choice; the other makes the choice carry real weight. On love and the inner life, Steins;Gate is far more nuanced, complete, and three-dimensional.",status:"published",reading_time:12,sidebar_label:"Detective Conan vs Steins;Gate",sidebar_position:20261007,description:"Same parts, inverted structure: one story freezes time to avoid a choice; the other makes the choice carry real weight. On love and the inner life, Steins;Gate is far more nuanced, complete, and three-dimensional."},sidebar:"docs",previous:{title:"Seven-Day Book: Body, Mind, and Spirit",permalink:"/en/docs/Diary/\u4e03\u65e5\u66f8\uff5c\u8eab\u5fc3\u9748"}},r={},l=[{value:"Identity: A Shell Forced On Him, and a Persona He Built Himself",id:"identity-a-shell-forced-on-him-and-a-persona-he-built-himself",level:2},{value:"The Childhood Friend: The One Who Waits, and the One Who Must Be Saved",id:"the-childhood-friend-the-one-who-waits-and-the-one-who-must-be-saved",level:2},{value:"The Girl Scientist: Both See Through Him \u2014 One Can&#39;t Win, One Does",id:"the-girl-scientist-both-see-through-him--one-cant-win-one-does",level:2},{value:"The Cost: Shelving the Choice, and Forcing the Protagonist to Choose",id:"the-cost-shelving-the-choice-and-forcing-the-protagonist-to-choose",level:2},{value:"What Remains After Loss",id:"what-remains-after-loss",level:2},{value:"Love Doesn&#39;t Need a Psychological Function Chart",id:"love-doesnt-need-a-psychological-function-chart",level:2},{value:"Conclusion: Whether the Author Will Let the Characters Pay",id:"conclusion-whether-the-author-will-let-the-characters-pay",level:2}];function c(e){const t={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:"Author: Nebula Walker\nDate: 07OCT2026\nMYTHOGEN ENGINE (mythogenengine.com)"}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"\ud83d\udccc Same parts, inverted structure: one story freezes time to avoid a choice; the other makes the choice carry real weight. On love and the inner life, Steins;Gate is far more nuanced, complete, and three-dimensional."})}),"\n",(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"detective-conan-vs-steinsgate",children:"Detective Conan vs Steins;Gate"})}),"\n",(0,i.jsx)(t.p,{children:"One is a mystery manga serialised since the nineties; the other is an anime adapted from a time-travel visual novel. On the surface, they have little in common. Take them apart, though, and the components are almost identical: one person with two identities; a childhood friend; a genius girl scientist who knows the protagonist's biggest secret; and, in the end, a protagonist who has to choose between the two women."}),"\n",(0,i.jsxs)(t.p,{children:["The parts are the same, but the structure is inverted at every turn. This isn't a claim that ",(0,i.jsx)(t.em,{children:"Detective Conan"})," is bad. It's a mystery series; its achievement lies in solving cases, and in thirty years of unbroken serialisation. But when it comes to love and the characters' inner lives, putting the two works side by side shows that ",(0,i.jsx)(t.em,{children:"Steins;Gate"})," is far more nuanced, complete, and three-dimensional \u2014 and makes it much clearer what Conan's romance line is missing."]}),"\n",(0,i.jsxs)(t.p,{children:["First, the scope. For ",(0,i.jsx)(t.em,{children:"Detective Conan"}),", I've read the first one or two hundred chapters of the original manga, plus about ten of the films. I haven't seen the later London confession or the Kyoto arc. What follows is about Conan within that range."]}),"\n",(0,i.jsx)(t.h2,{id:"identity-a-shell-forced-on-him-and-a-persona-he-built-himself",children:"Identity: A Shell Forced On Him, and a Persona He Built Himself"}),"\n",(0,i.jsx)(t.p,{children:"Shinichi Kudo becomes Conan Edogawa against his will. Someone else forced the drug down his throat; the name was improvised on the spot; the glasses and the voice-changing bow tie exist so he can hide. But the person inside the shell doesn't change: just as arrogant, just as obsessed with deduction, just as unable to walk away from a case. The role changes; the personality stays the same."}),"\n",(0,i.jsx)(t.p,{children:"Rintaro Okabe's Hououin Kyouma is the exact opposite: a character he created himself. After Mayuri's grandmother dies, Mayuri stands at the grave staring up at the sky, as if she might follow her. So Okabe plays the mad scientist, declares her his \"hostage,\" and drags her back into the world of the living. From the very start, this chuunibyou persona existed to protect someone else."}),"\n",(0,i.jsx)(t.p,{children:"In the middle of the story, the world line resets again and again, Mayuri dies again and again, and Okabe is broken \u2014 he can't even keep up the act. Hououin Kyouma disappears, leaving only a shattered Rintaro Okabe; that's when Kurisu deliberately mimics his chuuni poses to lift his spirits. And for the final step, where he has to deceive the world itself, he can only succeed by becoming Hououin Kyouma once more."}),"\n",(0,i.jsx)(t.p,{children:"So the \"two in one\" of each work means very different things. Conan's two identities are one because his personality never split. Okabe's two identities are one because he went through the split and, in the end, took that persona back into himself."}),"\n",(0,i.jsx)(t.p,{children:"Some people read Conan through Jung's idea of \"integration,\" but they've applied it to the wrong work. The one who needs integration \u2014 and is saved only after achieving it \u2014 is Rintaro Okabe. Conan doesn't need integration. He just needs someone who can recognise him."}),"\n",(0,i.jsx)(t.h2,{id:"the-childhood-friend-the-one-who-waits-and-the-one-who-must-be-saved",children:"The Childhood Friend: The One Who Waits, and the One Who Must Be Saved"}),"\n",(0,i.jsx)(t.p,{children:"Ran Mouri's function in the story is to wait. She's the home Shinichi has to return to, and her job is to stay the same. A character whose job is not to change has a hard time becoming three-dimensional, because depth requires choices, costs, and change."}),"\n",(0,i.jsx)(t.p,{children:"So her emotions cycle through the same few: worry, anger, jealousy \u2014 plus karate. She has no storyline of her own; all her screen time derives from Shinichi's absence. Gosho Aoyama's Aoko Nakamori and Kazuha Toyama come from the same mould: childhood friend, good fighter, bickers with the male lead, waits for him."}),"\n",(0,i.jsx)(t.p,{children:"Mayuri Shiina is also a childhood friend \u2014 equally innocent, slow-spoken, unable to keep up with everyone's theories. But she has a world of her own: she makes cosplay costumes, carries on her grandmother's habits, believes the stars are still there in the daytime, and often reaches up towards the sky. She also knows she's Okabe's \"hostage\" \u2014 knows she's protected and relied upon \u2014 and that self-awareness means she isn't merely waiting passively."}),"\n",(0,i.jsx)(t.p,{children:"More importantly, Mayuri's death is the engine of the whole story. She dies in one way or another on world line after world line, and every one of Okabe's struggles is to save her. Ran is the one who waits for someone to come back; Mayuri is the one for whom the protagonist will risk everything to rewrite fate. The weight of those two positions is worlds apart."}),"\n",(0,i.jsx)(t.h2,{id:"the-girl-scientist-both-see-through-him--one-cant-win-one-does",children:"The Girl Scientist: Both See Through Him \u2014 One Can't Win, One Does"}),"\n",(0,i.jsx)(t.p,{children:"Ai Haibara and Kurisu Makise are the same type of character: genius scientist, sharp-tongued, composed, sharing a secret with the protagonist that nobody else knows. They have one more thing in common: both can recognise the person behind the mask."}),"\n",(0,i.jsx)(t.p,{children:"Haibara knew Shinichi Kudo from the Organisation's files; when she meets Conan in real life, she recognises at a glance that they are the same person. Ran lives with Conan every day and still treats him as someone else \u2014 partly because Shinichi deliberately hides it from her, but the result is that only Haibara sees the whole of him. Kurisu sees early on that Okabe's chuuni act is a shell, and later even imitates it to hold him up."}),"\n",(0,i.jsxs)(t.p,{children:["Haibara has her own past, guilt, and choices, and is far more three-dimensional than Ran. According to ",(0,i.jsx)(t.a,{href:"https://bunshun.jp/articles/-/62919?page=2",children:"a Bunshun Online report"}),", Gosho Aoyama has said her popularity far exceeded his expectations \u2014 the author may never have intended her to become so important."]}),"\n",(0,i.jsxs)(t.p,{children:["The difference lies in the ending. In Aoyama's works, the childhood friend almost never loses; Haibara is destined only to perfect the antidote and send him back to Ran. Kurisu, on the other hand, wins: she is the heroine of the ",(0,i.jsx)(t.em,{children:"Steins;Gate"})," anime."]}),"\n",(0,i.jsx)(t.h2,{id:"the-cost-shelving-the-choice-and-forcing-the-protagonist-to-choose",children:"The Cost: Shelving the Choice, and Forcing the Protagonist to Choose"}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"Detective Conan"}),"'s way of handling the love triangle is not to handle it. Conan's body is stuck at primary-school age, and time in Beika Town has all but stopped: thirty years have passed in reality, while only a short time has passed in the story. As long as he doesn't turn back into Shinichi, Ran keeps waiting, Haibara keeps him company, nobody has to be chosen, and nobody has to pay a price."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"Steins;Gate"})," doesn't give its protagonist that way out \u2014 and its choice is often misread. Many people think Okabe gives up Kurisu to save Mayuri. The fundamental reason is actually that the runaway world line will ultimately end in destruction; Kurisu and Okabe make the decision together \u2014 that Kurisu will be sacrificed."]}),"\n",(0,i.jsx)(t.p,{children:'Okabe is unwilling with every fibre of his being. Must it really come down to a choice between "saving the world" and "saving Kurisu"?'}),"\n",(0,i.jsx)(t.p,{children:"What's crueller is what comes after the decision. Mayuri survives, but the stretch of space-time the two of them lived through together is, in theory, erased. They faced life and death together and fell deeply in love, yet that memory leaves no trace on the world: nobody knows, nobody would believe it, and only a very few people have a vague sense of what happened. Okabe has to pretend the world is turning as usual, pretend nothing happened \u2014 even act as if this person never existed."}),"\n",(0,i.jsx)(t.p,{children:"In theory, this may be the most rational, most correct decision. But when was love ever that simple? Can he really treat it as nothing more than a long dream, and simply let her go? In the end, Okabe finds he can't."}),"\n",(0,i.jsx)(t.p,{children:"And the contradiction doesn't end there. Even if he hardens his heart and lets Kurisu go, this world line still heads towards collapse and destruction, which is why all sorts of rescue plans later become necessary to balance everything out. Her death, it turns out, never truly solved the problem."}),"\n",(0,i.jsx)(t.p,{children:"Take another step back: even if her sacrifice really could solve every problem, could Okabe let her go with a clear heart? Once it becomes clear that even her death can't save the whole, the choice becomes all the more helpless, all the more painful. The world line where Okabe finally finds both of them alive is one he wins only after giving up everything."}),"\n",(0,i.jsx)(t.h2,{id:"what-remains-after-loss",children:"What Remains After Loss"}),"\n",(0,i.jsxs)(t.p,{children:["What truly tests a relationship isn't how well two people click when they're together, but how much of one person remains after losing the other. ",(0,i.jsx)(t.em,{children:"Steins;Gate"})," runs this test twice, in opposite directions."]}),"\n",(0,i.jsxs)(t.p,{children:["The first time is ",(0,i.jsx)(t.em,{children:"Steins;Gate 0"}),". It's the world line where Kurisu is already dead: Okabe couldn't save her, so he gave up. He takes off the lab coat, stops calling himself Hououin Kyouma, becomes a quiet, ordinary university student, and locks everything he went through inside. All that's left of Kurisu is \"Amadeus\" \u2014 an artificial intelligence built from her memory data, which can talk and make sarcastic remarks, but isn't her."]}),"\n",(0,i.jsx)(t.p,{children:"This instalment also gives Okabe someone who seems like a possible replacement: Maho Hiyajo, Kurisu's senior at the research institute, just as smart, and just as capable of understanding what he's doing. But the work itself refuses to let her become a substitute. Maho keeps comparing herself to Salieri and Kurisu to Mozart; naming the AI \"Amadeus\" is exactly that metaphor. She lives in Kurisu's shadow, and she knows it."}),"\n",(0,i.jsx)(t.p,{children:"Without Kurisu, Hououin Kyouma doesn't exist. The persona was originally born for Mayuri; in this instalment, it's the reverse \u2014 Mayuri is the one hoping he'll become Hououin Kyouma again and bring Kurisu back. Only when Okabe puts the lab coat back on and resolves once more to rewrite fate does the persona return. Half of his personality died with her, and only by saving her can it be made whole."}),"\n",(0,i.jsxs)(t.p,{children:["The second time is the film ",(0,i.jsx)(t.em,{children:"Load Region of D\xe9j\xe0 Vu"}),", and the direction is reversed. Having leapt across too many world lines, Okabe begins to be rejected by the world, fading bit by bit from everyone's memory. Only Kurisu keeps feeling an inexplicable d\xe9j\xe0 vu, a constant sense that someone is missing. In the end, she becomes the time leaper, goes back into the past to rescue him, and passes the chuunibyou she once caught from him back to him."]}),"\n",(0,i.jsx)(t.p,{children:"Only when the two works are taken together is the bond complete \u2014 living and dying as one: without her, he isn't whole; without him, she'll turn the whole world upside down to find him. This isn't one side guarding and the other being guarded, but a two-way relationship that collapses if either side is missing."}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"Detective Conan"})," has never run this kind of test. Haibara and Conan have covered for each other in danger countless times, but the story has never asked: if Haibara were gone, how much of Conan would remain? The same goes for Ran: she's always waiting, yet she has never truly lost him \u2014 he lives in her house."]}),"\n",(0,i.jsx)(t.p,{children:"Without loss, there's no way to measure how deep love goes."}),"\n",(0,i.jsx)(t.h2,{id:"love-doesnt-need-a-psychological-function-chart",children:"Love Doesn't Need a Psychological Function Chart"}),"\n",(0,i.jsx)(t.p,{children:'There\'s a popular style of writing online: stick psychological labels on the characters \u2014 light and shadow, persona, the Shadow, individuation \u2014 and then deduce what each relationship "represents." Ran represents the past and continuity, Haibara represents post-traumatic understanding, Conan is the mask, and the perfect ending is "integration."'}),"\n",(0,i.jsx)(t.p,{children:'This style claims to reject the matchmaking calculus of "who suits Shinichi better," but in practice it calculates even more finely: who knows which version of him, who carries the light, who carries the shadow, who is responsible for bringing him back to wholeness. The pairing chart has just been swapped for a psychological function chart; the calculation hasn\'t shrunk one bit.'}),"\n",(0,i.jsx)(t.p,{children:"The first problem is that it's applied to the wrong work. As noted above, Conan's personality never split, so there's nothing to integrate; the one who truly split and took the persona back into himself is Rintaro Okabe. The theory comes before the work, and the work is made to fit the theory."}),"\n",(0,i.jsxs)(t.p,{children:["The second problem is that it fits too smoothly. The same framework can be applied to ",(0,i.jsx)(t.em,{children:"Sailor Moon"}),", ",(0,i.jsx)(t.em,{children:"Naruto"}),", ",(0,i.jsx)(t.em,{children:"Inuyasha"}),", or ",(0,i.jsx)(t.em,{children:"Slam Dunk"}),", and the conclusion is always: accept the shadow, move towards wholeness. Change the work, swap a few character names, and the conclusion doesn't need to change. A framework that can explain every work doesn't actually explain any of them."]}),"\n",(0,i.jsx)(t.p,{children:"The third problem is that it can never be wrong. If the ending picks Ran, that's a return to continuity; if it picks Haibara, that's accepting the shadow; if it picks no one, that's individuation complete. An analysis that's right no matter what is no analysis at all."}),"\n",(0,i.jsx)(t.p,{children:"This article hasn't used a single psychological term. It simply places the two works side by side: who was forced into a shell and who built a persona himself; who waits and who must be saved; who shelves the choice and who pays the price. The differences surface on their own."}),"\n",(0,i.jsx)(t.p,{children:"As for why one would pick Haibara, or pick Kurisu, no theory is needed either. Their bond with the protagonist is one of living and dying together: understanding each other in a situation only they know about, perfectly in sync, and, when it counts, each willing to give everything for the other \u2014 even to sacrifice themselves. Haibara can stay in a building about to explode to count down for everyone, while also researching the antidote that will send him back to someone else; Kurisu, knowing full well her death is the price for putting the world back on track, still makes the decision together with Okabe. Conversely, Conan steps in front of Haibara time and again, and Okabe goes back in time and starts over for Kurisu. This kind of love doesn't first need to prove which function the other person serves in the structure of one's life."}),"\n",(0,i.jsx)(t.h2,{id:"conclusion-whether-the-author-will-let-the-characters-pay",children:"Conclusion: Whether the Author Will Let the Characters Pay"}),"\n",(0,i.jsxs)(t.p,{children:["Picking Haibara in ",(0,i.jsx)(t.em,{children:"Detective Conan"})," and picking Kurisu in ",(0,i.jsx)(t.em,{children:"Steins;Gate"})," come down to the same reason: they live and die with the protagonist, and are willing to give everything for each other."]}),"\n",(0,i.jsxs)(t.p,{children:["The difference is that ",(0,i.jsx)(t.em,{children:"Steins;Gate"})," gives the choice real weight: Mayuri, Kurisu, and the whole world are on the scales, and whichever way the protagonist chooses, he loses something. In ",(0,i.jsx)(t.em,{children:"Detective Conan"}),', the childhood friend is trapped in a template, the choice looks too easy, and the author can only keep it suspended with "never growing up."']}),"\n",(0,i.jsxs)(t.p,{children:["One work admits that choices have costs; the other uses frozen time to avoid them. This isn't necessarily a question of which is better: ",(0,i.jsx)(t.em,{children:"Detective Conan"})," has always had deduction at its core, with the romance as seasoning between cases, while ",(0,i.jsx)(t.em,{children:"Steins;Gate"})," puts love and choice at the very centre of the story. But if the subject is love and the human heart, the latter is far more nuanced, complete, and three-dimensional."]})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>h});var i=n(96540);const a={},s=i.createContext(a);function o(e){const t=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function h(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),i.createElement(s.Provider,{value:t},e.children)}}}]);